    Vector2f farthest;
    float maxDot = -FLT_MAX;
    for (const Vertex& vertex : shape->getPoints()) {
        Vector2f point = vertex.position;
        float dot = direction.dot(point);
        if (dot > maxDot) {
            maxDot = dot;
            farthest = point;
        }
    }
    return farthest;
}

